        // convert to rows local to that LOD for the gather.
        const base = cum[lodValue];
        const orderedLocal = new Uint32Array(totalIndices);
        for (let j = 0; j < totalIndices; ++j)
            orderedLocal[j] = orderedIndices[j] - base;
